-- Independent sealed holdout only. No real run/task or annotation is inserted.
create table public.analysis_jev_independent_configurations(
 id text primary key,config jsonb not null,config_sha256 text not null check(config_sha256 ~ '^[a-f0-9]{64}$'),frozen_at timestamptz not null default now(),
 check(config->>'experimental_only'='true' and config->>'production_enabled'='false')
);
create table public.analysis_jev_independent_runs(
 id uuid primary key default gen_random_uuid(),holdout_id uuid not null references public.analysis_v11_independent_holdout_sets(id),
 organization_id uuid not null references public.organizations(id),establishment_id uuid not null references public.establishments(id),
 configuration_id text not null references public.analysis_jev_independent_configurations(id),config jsonb not null,prepared jsonb not null,
 status text not null default 'queued' check(status in ('queued','running','completed','failed')),created_by uuid not null references auth.users(id),
 cost_confirmed_at timestamptz not null default now(),created_at timestamptz not null default now(),started_at timestamptz,completed_at timestamptz,error_code text,lease_owner uuid,lease_until timestamptz,
 unique(holdout_id,configuration_id)
);
create table public.analysis_jev_independent_tasks(
 id uuid primary key default gen_random_uuid(),run_id uuid not null references public.analysis_jev_independent_runs(id),
 review_id uuid not null,model_version text not null check(model_version in ('v11','v12')),analysis_text_sha256 text not null,
 review_alias text not null,question_set text not null,repeat integer not null check(repeat between 1 and 3),
 status text not null default 'pending' check(status in ('pending','running','completed','failed')),response jsonb,served_model text,
 input_tokens bigint not null default 0,output_tokens bigint not null default 0,request_count integer not null default 0 check(request_count between 0 and 1),
 retry_count integer not null default 0 check(retry_count=0),cost_usd double precision not null default 0,duration_ms bigint not null default 0,
 error_code text,usage_complete boolean not null default true,lease_owner uuid,started_at timestamptz,completed_at timestamptz,
 unique(run_id,model_version,review_id,repeat)
);
create index independent_jev_pending_tasks on public.analysis_jev_independent_tasks(run_id,status);
create table public.analysis_jev_independent_results(
 run_id uuid primary key references public.analysis_jev_independent_runs(id),comparison jsonb not null,created_at timestamptz not null default now(),
 check(comparison->>'human_validated'='false' and comparison->>'production_enabled'='false' and comparison->>'reference_type'='sealed_blind_ai_reference_not_human_gold')
);
do $$ declare t text;begin
 foreach t in array array['analysis_jev_independent_configurations','analysis_jev_independent_runs','analysis_jev_independent_tasks','analysis_jev_independent_results'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);
 if t='analysis_jev_independent_configurations' then
 execute format('create policy independent_jev_read on public.%I for select to authenticated using(exists(select 1 from public.organization_members m where m.user_id=(select auth.uid()) and m.role in (''owner'',''admin'',''manager'')))',t);
 elsif t='analysis_jev_independent_runs' then
 execute format('create policy independent_jev_read on public.%I for select to authenticated using(exists(select 1 from public.organization_members m where m.organization_id=%I.organization_id and m.user_id=(select auth.uid()) and m.role in (''owner'',''admin'',''manager'')))',t,t);
 else
 execute format('create policy independent_jev_read on public.%I for select to authenticated using(exists(select 1 from public.analysis_jev_independent_runs r join public.organization_members m on m.organization_id=r.organization_id where r.id=%I.run_id and m.user_id=(select auth.uid()) and m.role in (''owner'',''admin'',''manager'')))',t,t);end if;
 end loop;end $$;
create function public.independent_jev_guard() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if tg_op='DELETE' then raise exception 'INDEPENDENT_IMMUTABLE';end if;
 if tg_table_name='analysis_jev_independent_runs' then
 if old.status in ('completed','failed') or (to_jsonb(new)-array['status','started_at','completed_at','error_code','lease_owner','lease_until']) is distinct from (to_jsonb(old)-array['status','started_at','completed_at','error_code','lease_owner','lease_until']) then raise exception 'INDEPENDENT_IMMUTABLE';end if;
 elsif tg_table_name='analysis_jev_independent_tasks' then
 if old.status in ('completed','failed') or (to_jsonb(new)-array['status','response','served_model','input_tokens','output_tokens','request_count','retry_count','cost_usd','duration_ms','error_code','usage_complete','lease_owner','started_at','completed_at']) is distinct from (to_jsonb(old)-array['status','response','served_model','input_tokens','output_tokens','request_count','retry_count','cost_usd','duration_ms','error_code','usage_complete','lease_owner','started_at','completed_at']) then raise exception 'INDEPENDENT_IMMUTABLE';end if;
 else raise exception 'INDEPENDENT_IMMUTABLE';end if;return new;
end $$;
create trigger independent_jev_config_immutable before update or delete on public.analysis_jev_independent_configurations for each row execute function public.independent_jev_guard();
create trigger independent_jev_run_immutable before update or delete on public.analysis_jev_independent_runs for each row execute function public.independent_jev_guard();
create trigger independent_jev_task_immutable before update or delete on public.analysis_jev_independent_tasks for each row execute function public.independent_jev_guard();
create trigger independent_jev_result_immutable before update or delete on public.analysis_jev_independent_results for each row execute function public.independent_jev_guard();
